// Generated by generator/bundle.js from .env.example, nginx/catalog.conf.tmpl, nginx/portal.conf.tmpl, readium/config.yaml.tmpl. Do not edit: npm run bundle.
export const TEMPLATES = {
  ".env.example": "# ELVIRA settings: one file for Docker Compose, plain Docker and Kubernetes.\n#\n#   npm run configure      writes .env from elvira.json, with fresh secrets (keeps existing ones)\n#   cp .env.example .env   and edit by hand, if you prefer\n#\n# Never commit .env: it holds your secrets.\n\n# =================================================================== what runs\n# Profiles to start, comma-separated (compose.yml lists them all).\nCOMPOSE_PROFILES=postgres,redis\nCOMPOSE_PROJECT_NAME=elvira\n\n# stable = master images, develop = develop images (search, OCR, extraction).\nELVIRA_CATALOG_IMAGE=ghcr.io/evilflowerscatalog/evilflowerscatalog:master\nELVIRA_LCPENCRYPT_IMAGE=ghcr.io/evilflowerscatalog/evilflowers-lcpencrypt-worker:master\n\n# =================================================================== addresses\n# Where readers and apps reach the catalog, and where the portal is served from.\nELVIRA_DOMAIN=library.example.org\nELVIRA_PORTAL_DOMAIN=portal.example.org\n# 127.0.0.1 with nginx on this machine; 0.0.0.0 if your proxy runs elsewhere.\nELVIRA_HTTP_BIND=127.0.0.1\n\nINSTANCE_NAME=library.example.org\nALLOWED_HOSTS=library.example.org;evilflowers\nEVILFLOWERS_BASE_URL=https://library.example.org\nEVILFLOWERS_READIUM_BASE_URL=https://library.example.org\nEVILFLOWERS_PORTAL_URL=https://portal.example.org\n# The only browser origin allowed to call the API.\nCORS_ALLOWED_ORIGINS=https://portal.example.org\nEVILFLOWERS_CONTACT_EMAIL=library@example.org\n\n# =================================================================== catalog\nDJANGO_SETTINGS_MODULE=evil_flowers_catalog.settings.production\nSECRET_KEY=change-me\n# RSA private key (JWK, one line) that signs access tokens. npm run configure makes one.\nSECURED_VIEW_JWK=change-me\nGUNICORN_CMD_ARGS=-w 4 -b 0.0.0.0:8000 --keep-alive 75\n# One proxy (nginx) in front appends to X-Forwarded-For.\nEVILFLOWERS_RATE_LIMIT_PROXY_COUNT=1\nEVILFLOWERS_LOG_FORMAT=json\nEVILFLOWERS_STORAGE_DRIVER=apps.files.storage.filesystem.FileSystemStorage\nEVILFLOWERS_STORAGE_FILESYSTEM_DATADIR=/var/local/evilflowers\n\n# =================================================================== PostgreSQL\n# postgres = the bundled one (profile postgres); your own server's name otherwise.\nPGHOST=postgres\nPGPORT=5432\nPGDATABASE=evilflowers\nPGUSER=evilflowers\nPGPASSWORD=change-me\n\n# =================================================================== Redis and Celery\nREDIS_HOST=redis\nREDIS_PORT=6379\nREDIS_DATABASE=1\nCELERY_BROKER_URL=redis://redis:6379/7\nCELERY_RESULT_BACKEND=redis://redis:6379/7\nCELERY_BROKER_VISIBILITY_TIMEOUT=43200\nCELERY_WORKER_CONCURRENCY=2\n# The one worker also runs the nightly maintenance (backups, cleanup).\nEVILFLOWERS_MAINTENANCE_QUEUE=celery\nEVILFLOWERS_EVENT_BROKER_EXECUTOR=apps.events.services.CeleryEventExecutionService\nEVILFLOWERS_EVENT_BROKER_TRANSFORMER=apps.events.transformers.DjangoTransformer\n\n# =================================================================== MCP server for AI agents (/mcp/v1)\nEVILFLOWERS_MCP_ENABLED=1\nEVILFLOWERS_MCP_AUTHENTICATION_SCHEMAS=Bearer\n\n# =================================================================== lending (profile lending)\n# User and password of the license servers; npm run configure writes config/readium/ from them.\nELVIRA_READIUM_USER=evilflowers\nELVIRA_READIUM_PASSWORD=change-me\nEVILFLOWERS_READIUM_LCPSV_URL=http://evilflowers:change-me@readium:8989\nEVILFLOWERS_READIUM_LSDSV_URL=http://evilflowers:change-me@readium:8990\nEVILFLOWERS_READIUM_LCPENCRYPT_NOTIFY_URL=http://evilflowers:8000/readium/v1/hooks/encryption\nEVILFLOWERS_READIUM_LCPENCRYPT_REPORT_URL=http://evilflowers:8000/readium/v1/hooks/encryption/result\n# test = EDRLab's test certificate in the image (test apps only); production = readium/certs/.\nELVIRA_LCP_CERTIFICATE=test\n\n# =================================================================== OCR (profile ocr, develop)\nEVILFLOWERS_OCR_ENABLED=false\nEVILFLOWERS_OCR_QUEUE=evilflowers_ocr_worker\n\n# =================================================================== search by meaning (profile search, develop)\n# http://tei-embed with the profile, your own service's URL otherwise, empty = words only.\nEVILFLOWERS_EMBEDDING_URL=\nEVILFLOWERS_EMBEDDING_MODEL=intfloat/multilingual-e5-large-instruct@274baa43b0e13e37fafa6428dbc7938e62e5c439\nEVILFLOWERS_EMBEDDING_API_KEY=change-me\n\n# =================================================================== extraction (profile extraction, develop)\nEVILFLOWERS_EXTRACTION_ENABLED=0\n# API key of the catalog's extraction service user: scripts/extraction-api-key.sh prints one.\nEXTRACTION_API_KEY=\n\n# =================================================================== reading assistant (profile assistant, or your Ollama API)\nEVILFLOWERS_ASSISTANT_ENABLED=0\nEVILFLOWERS_ASSISTANT_OLLAMA_ENDPOINT=http://ollama:11434/api/chat\nEVILFLOWERS_ASSISTANT_OLLAMA_MODEL=qwen3.6:35b-a3b-q4_K_M\nEVILFLOWERS_ASSISTANT_OLLAMA_API_KEY=\nEVILFLOWERS_ASSISTANT_OLLAMA_THINK=0\nEVILFLOWERS_ASSISTANT_OLLAMA_NUM_CTX=32768\n\n# =================================================================== e-mail\n# maildev with the profile mail (port 1025, no TLS); your SMTP server otherwise.\nEVILFLOWERS_NOTIFICATIONS_ENABLED=false\nEMAIL_HOST=\nEMAIL_PORT=587\nEMAIL_USE_TLS=true\nEMAIL_HOST_USER=\nEMAIL_HOST_PASSWORD=\nDEFAULT_FROM_EMAIL=library@example.org\n\n# =================================================================== nightly database backup to S3\n# Empty schedule = no backup.\nEVILFLOWERS_BACKUP_SCHEDULE=\nEVILFLOWERS_BACKUP_DESTINATION=s3://backups/evilflowers\nEVILFLOWERS_BACKUP_S3_HOST=s3.example.org\nEVILFLOWERS_BACKUP_S3_SECURE=1\nEVILFLOWERS_BACKUP_S3_ACCESS_KEY=\nEVILFLOWERS_BACKUP_S3_SECRET_KEY=\n\n# =================================================================== traces, metrics and logs\n# http://otel-lgtm:4318 with the profile telemetry, your collector otherwise.\nOTEL_SDK_DISABLED=true\nOTEL_EXPORTER_OTLP_ENDPOINT=\nOTEL_RESOURCE_ATTRIBUTES=service.namespace=elvira,deployment.environment.name=production\n",
  "nginx/catalog.conf.tmpl": "# ELVIRA catalog behind nginx. `npm run configure` writes config/nginx/catalog.conf from this\n# template; copy that to /etc/nginx/conf.d/ (the Ansible playbook does it for you).\n#\n# Port 80 only: `certbot --nginx -d ${ELVIRA_DOMAIN}` then adds TLS and the redirect.\n\nupstream elvira_catalog {\n    # The catalog container, published on loopback by compose.yml.\n    server 127.0.0.1:8000;\n    # Idle connections to gunicorn, whose --keep-alive (75 s) outlasts nginx's 60 s.\n    keepalive 16;\n}\n\nserver {\n    listen 80;\n    listen [::]:80;\n    server_name ${ELVIRA_DOMAIN};\n    server_tokens off;\n\n    # Publication uploads.\n    client_max_body_size 500m;\n\n    # Set here once: a location with its own proxy_set_header would inherit none of these.\n    # The catalog builds every absolute link (OPDS, covers, LCP licences) from Host and treats\n    # requests for its public name as https.\n    proxy_set_header Host $host;\n    proxy_set_header X-Real-IP $remote_addr;\n    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n    proxy_set_header X-Forwarded-Proto $scheme;\n    proxy_http_version 1.1;\n    proxy_set_header Connection \"\";\n\n    # Gunicorn gives a request 240 s; wait a little longer.\n    proxy_connect_timeout 300s;\n    proxy_send_timeout 300s;\n    proxy_read_timeout 300s;\n    send_timeout 300s;\n\n    # The catalog compresses its own responses.\n    gzip off;\n\n    location / {\n        proxy_pass http://elvira_catalog;\n    }\n\n    # Publications and covers. Never cache here: downloads are per reader.\n    location /data/v1/ {\n        proxy_pass http://elvira_catalog;\n    }\n\n    # The admin assets, collected into the installation directory at every start.\n    location /static/ {\n        alias ${ELVIRA_DIR}/static/;\n        expires 1d;\n        access_log off;\n    }\n\n    # Streamed answers (text/event-stream) go out as they are written.\n    location /assistant/v1/ {\n        proxy_pass http://elvira_catalog;\n        proxy_buffering off;\n        proxy_read_timeout 600s;\n    }\n    location = /mcp/v1 {\n        proxy_pass http://elvira_catalog;\n        proxy_buffering off;\n        proxy_read_timeout 600s;\n    }\n}\n",
  "nginx/portal.conf.tmpl": "# elvira-portal, the readers' web app: a single-page app built into ${ELVIRA_PORTAL_ROOT}.\n# `npm run configure` writes config/nginx/portal.conf from this template.\n#\n# Port 80 only: `certbot --nginx -d ${ELVIRA_PORTAL_DOMAIN}` then adds TLS and the redirect.\n\n# Hashed chunks (Vite: /assets/name-<8 characters>.ext) are cached for a year, everything else\n# revalidated on every load. Keyed on the status, so a missing chunk is never pinned.\nmap \"$status:$uri\" $elvira_portal_cache_control {\n    \"~^(?:200|206|304):/assets/[^/]+-[A-Za-z0-9_-]{8}\\.(?:js|mjs|css|woff2?|ttf|png|jpe?g|gif|svg|webp|avif|wasm)$\" \"public, max-age=31536000, immutable\";\n    default \"no-cache\";\n}\n\nserver {\n    listen 80;\n    listen [::]:80;\n    server_name ${ELVIRA_PORTAL_DOMAIN};\n    server_tokens off;\n\n    root ${ELVIRA_PORTAL_ROOT};\n    index index.html;\n\n    gzip on;\n    gzip_vary on;\n    gzip_types text/plain text/css application/json application/javascript text/xml application/xml image/svg+xml;\n\n    # At server level only: an add_header inside a location drops every inherited one.\n    add_header Cache-Control $elvira_portal_cache_control always;\n\n    # Deep links are routes of the app.\n    location / {\n        try_files $uri $uri/ /index.html;\n    }\n\n    # A missing chunk (a tab opened before the last deploy) is a 404, not index.html as JavaScript.\n    location ~ \"^/assets/[^/]+-[A-Za-z0-9_-]{8}\\.(?:js|mjs|css|woff2?|ttf|png|jpe?g|gif|svg|webp|avif|wasm)$\" {\n        try_files $uri =404;\n    }\n}\n",
  "readium/config.yaml.tmpl": "# Readium LCP License (lcp) and Status (lsd) servers. The generator writes this file to\n# config/readium/config.yaml with ${…} filled in; edit the template, not the result.\n#\n# Every public link points at the catalog, which proxies licences, status documents and\n# encrypted content under /readium/v1/: readers never reach ports 8989/8990.\n\n# \"basic\" accepts EDRLab's test certificate; production certificates from EDRLab need \"1.0\".\nprofile: \"${ELVIRA_LCP_PROFILE}\"\n\nlcp:\n  host: \"0.0.0.0\"\n  port: 8989\n  public_base_url: \"https://${ELVIRA_DOMAIN}/readium/v1\"\n  database: \"sqlite3://file:/usr/local/var/readium/db/lcp.sqlite?cache=shared&mode=rwc\"\n  auth_file: \"/usr/local/etc/readium/htpasswd\"\n\nlsd:\n  host: \"0.0.0.0\"\n  port: 8990\n  public_base_url: \"https://${ELVIRA_DOMAIN}/readium/v1\"\n  database: \"sqlite3://file:/usr/local/var/readium/db/lsd.sqlite?cache=shared&mode=rwc\"\n  auth_file: \"/usr/local/etc/readium/htpasswd\"\n  license_link_url: \"https://${ELVIRA_DOMAIN}/readium/v1/licenses/{license_id}.lcpl\"\n\ncertificate:\n  cert: \"${ELVIRA_LCP_CERT}\"\n  private_key: \"${ELVIRA_LCP_KEY}\"\n\nlicense:\n  links:\n    status: \"https://${ELVIRA_DOMAIN}/readium/v1/licenses/{license_id}/status\"\n    hint: \"https://${ELVIRA_DOMAIN}/readium/v1/hint\"\n    publication: \"https://${ELVIRA_DOMAIN}/readium/v1/content/{publication_id}\"\n\n# lcpencrypt writes the encrypted copies into the shared data volume.\nstorage:\n  mode: \"fs\"\n  filesystem:\n    directory: \"/var/local/evilflowers\"\n\nlicense_status:\n  register: true\n  renew: true\n  return: true\n  renting_days: 14\n  renew_days: 14\n\n# The status server tells the license server about returns and renewals with these.\nlsd_notify_auth:\n  username: \"${ELVIRA_READIUM_USER}\"\n  password: \"${ELVIRA_READIUM_PASSWORD}\"\nlcp_update_auth:\n  username: \"${ELVIRA_READIUM_USER}\"\n  password: \"${ELVIRA_READIUM_PASSWORD}\"\n",
};
